steps.script:
GameState.state["factions"]["1"].merge({"detachment": "Kult of Speed"}, true)
StratagemManager.load_faction_stratagems_for_player(1)
var u = GameState.state.units
var bm: Array = u["U_RUKKATRUKK_SQUIGBUGGIES_A"].models
for i in range(bm.size()):
	bm[i]["position"] = {"x": (6.0 + i * 3.5) * 40.0, "y": 57.5 * 40.0}
var ko: Array = u["U_KOMMANDOS_A"].models
for i in range(ko.size()):
	ko[i]["position"] = {"x": (2.0 + (i % 5) * 1.4) * 40.0, "y": (49.0 - int(i / 5) * 1.4) * 40.0}
ko[ko.size() - 1]["alive"] = false
ko[ko.size() - 1]["current_wounds"] = 0
PhaseManager.get_current_phase_instance().game_state_snapshot = GameState.create_snapshot()
tree.current_scene._recreate_unit_visuals()
var M = load("res://scripts/stratagems/ork_codex/OrkCodexMovement.gd")
return M.delicious_squigs_targets("U_RUKKATRUKK_SQUIGBUGGIES_A", 1)

var ov = tree.current_scene.ghost_layer.get_node_or_null("ReviveSetupPreview")
if ov == null or ov.markers.size() != 1:
	return false
return float(ov.markers[0].position.y) > 2000.0

var rv = GameState.state.units["U_KOMMANDOS_A"].models[9]
for uid in GameState.state.units:
	for m in GameState.state.units[uid].models:
		if m == rv or not m.get("alive", true) or m.get("position") == null:
			continue
		if Measurement.models_overlap(rv, m):
			return false
return true

var mid = str(GameState.state.units["U_KOMMANDOS_A"].models[9].id)
var mp = GameState.state.units["U_KOMMANDOS_A"].models[9].position
for t in tree.current_scene.token_layer.get_children():
	if str(t.get_meta("unit_id", "")) == "U_KOMMANDOS_A" and str(t.get_meta("model_id", "")) == mid:
		return t.visible and t.position.distance_to(Vector2(float(mp.x), float(mp.y))) < 2.0
return false
